using System.Windows; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using AutoPecasERP.Services.Seguranca;
namespace AutoPecasERP.Desktop.Views;
public partial class MainWindow:Window { readonly Usuario _usuario; public MainWindow(Usuario u){InitializeComponent();_usuario=u;Welcome.Text=$"Bem-vindo, {u.Nome} • Perfil: {u.Perfil}";} async Task<bool> Pode(string modulo){using var db=new ErpDbContext();var ok=await new PermissaoService(db).PodeAsync(_usuario.Perfil,modulo);if(!ok)MessageBox.Show("Seu perfil não possui permissão para este módulo.","Acesso negado");return ok;} async void Seguranca_Click(object s,RoutedEventArgs e){if(!await Pode("Seguranca"))return;new SegurancaBackupWindow(){Owner=this}.ShowDialog();} async void Relatorios_Click(object s,RoutedEventArgs e){if(!await Pode("Relatorios"))return;new RelatoriosWindow(){Owner=this}.ShowDialog();} async void Crm_Click(object s,RoutedEventArgs e){if(!await Pode("CRM"))return;new CrmWindow(_usuario){Owner=this}.ShowDialog();} async void Oficina_Click(object s,RoutedEventArgs e){if(!await Pode("Oficina"))return;new OficinaWindow(_usuario){Owner=this}.ShowDialog();} async void Financeiro_Click(object s,RoutedEventArgs e){if(!await Pode("Financeiro"))return;new FinanceiroWindow(_usuario){Owner=this}.ShowDialog();} async void Fiscal_Click(object s,RoutedEventArgs e){if(!await Pode("Fiscal"))return;new ConfiguracaoFiscalWindow(){Owner=this}.ShowDialog();} async void Pdv_Click(object s,RoutedEventArgs e){if(!await Pode("PDV"))return;new PdvWindow(_usuario){Owner=this}.ShowDialog();} async void Clientes_Click(object s,RoutedEventArgs e){if(!await Pode("Clientes"))return;new ClientesWindow{Owner=this}.ShowDialog();}
async void Produtos_Click(object s,RoutedEventArgs e){if(!await Pode("Produtos"))return;new ProdutosWindow{Owner=this}.ShowDialog();}
async void Fornecedores_Click(object s,RoutedEventArgs e){if(!await Pode("Fornecedores"))return;new FornecedoresWindow{Owner=this}.ShowDialog();}
async void Compras_Click(object s,RoutedEventArgs e){if(!await Pode("Compras"))return;new ComprasWindow{Owner=this}.ShowDialog();} async void Reposicao_Click(object s,RoutedEventArgs e){if(!await Pode("Estoque"))return;new ReposicaoEstoqueWindow{Owner=this}.ShowDialog();}
}